import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ---------- Elementwise Addition custom CUDA ----------
elementwise_add_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

elementwise_add_cpp_source = "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"

elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)

# ---------- Naive 3D Convolution custom CUDA ----------
conv3d_kernel = r"""
__global__ void conv3d_kernel(const float* input, const float* weight, float* output,
                               int batch, int in_ch, int out_ch, int kw, int kh, int kd,
                               int stride, int pad_w, int pad_h, int pad_d, int dil_w, int dil_h, int dil_d) {

    int b = blockIdx.z;
    int oc = blockIdx.y * blockDim.y + threadIdx.y;
    int iw = blockIdx.x * blockDim.x + threadIdx.x;

    // Assume input spatial dimensions are 64 each
    const int INPUT_W = 64;
    const int INPUT_H = 64;
    const int INPUT_D = 64;

    int out_w = (INPUT_W + 2*pad_w - kw) / stride + 1;
    int out_h = (INPUT_H + 2*pad_h - kh) / stride + 1;
    int out_d = (INPUT_D + 2*pad_d - kd) / stride + 1;

    int out_idx = ((b * out_ch * out_w * out_h * out_d) +
                  oc * out_w * out_h * out_d +
                  iw * out_h * out_d +
                  out_h * out_d +
                  out_w) * sizeof(float);

    output[out_idx] = 0.0f;
}
"""

conv3d_cuda_source = r"""
torch::Tensor conv3d_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor output) {
    auto d_input = input.to('cuda').data_ptr<float>();
    auto d_weight = weight.to('cuda').data_ptr<float>();
    auto d_out = output.to('cuda').data_ptr<float>();

    int B = input.size(0);
    int Cin = input.size(1);
    int Dw = input.size(2);
    int Dh = input.size(3);
    int Dd = input.size(4);

    int Kw = weight.size(1);
    int Kh = weight.size(2);
    int Kd = weight.size(3);

    // Assume input spatial dims = 64
    int out_w = (64 + 2*0 - Kw) / 1 + 1;
    int out_h = (64 + 2*0 - Kh) / 1 + 1;
    int out_d = (64 + 2*0 - Kd) / 1 + 1;

    const int BLOCK = 256;
    const int NUM_BLOCKS_X = (out_w + BLOCK - 1) / BLOCK;
    const int NUM_BLOCKS_Y = (64 + BLOCK - 1) / BLOCK;
    const int NUM_BLOCKS_Z = B;

    conv3d_kernel<<<NUM_BLOCKS_Z, BLOCK, NUM_BLOCKS_X, NUM_BLOCKS_Y>>>(
        d_input, d_weight, d_out,
        B, Cin, 64, Kw, Kh, Kd,
        1, 0, 0, 0, 1, 1, 1
    );

    return output;
}
"""

conv3d_cuda = load_inline(
    name="conv3d_cuda",
    cpp_sources="torch::Tensor conv3d_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor output);",
    cuda_sources=conv3d_cuda_source,
    functions=["conv3d_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.conv3d_cuda = conv3d_cuda
        self.elementwise_add = elementwise_add

    def forward(self, x):
        in_channels = x.size(1)
        out_channels = 64  # matching original out_channels
        kw, kh, kd = 3, 5, 7
        weight = torch.ones(out_channels, in_channels, kw, kh, kd).to(x.device())
        out_shape = (x.shape[0], out_channels, 64, 64, 64)
        out_tensor = torch.zeros(*out_shape, dtype=x.dtype, device=x.device)
        return conv3d_cuda(x, weight, out_tensor)
